91	}
92	
93	// --- boot ---
94	const world = makeWorld(document.getElementById('gl'));
95	bindCurve(world);
96	const fx = makeFX(world.scene);
97	const glowT = glowTex();
98	const audio = makeAudio();
99	const ui = makeUI({
100	  onSpeed: toggleSpeed, onPause: togglePause, onMute: () => ui.mute(audio.toggleMute()),
101	  onCall: () => callWave(true), onUpgrade: upgradeSel, onSell: sellSel, onDeselect: deselect,
102	  onBuild: (key) => buildOn(key), onStart: () => startGame(false),
103	  onSkill: (key) => { if (key === 'Q') castStarfall(); else if (key === 'E') castNova(); else if (key === 'R') castOverload(); },
104	});
105	
106	// --- protocol (site bridge) ---
107	function report(kind, payload = {}) {
108	  const frame = { kind, ...payload };
109	  reports.push(frame);
110	  try {
111	    if (reportTarget) reportTarget(frame);
112	    else if (window.parent !== window) window.parent.postMessage({ source: 'lightgame', type: 'lightgame:report', payload: frame }, '*');
113	  } catch (e) { }
114	}
115	G.setReportTarget = (fn) => { reportTarget = fn; };
116	report('ready', { game: 'starfall-bulwark' });
117	
118	// --- waves / director ---
119	function waveComp(w) {
120	  if (!endless && w <= TOTAL_WAVES) return WAVES[w - 1] || WAVES[0];
121	  const idx = Math.max(0, w - TOTAL_WAVES - 1);
122	  const base = WAVES[idx % 10].map(x => [...x]);
123	  const comp = base.filter(g => g[0] !== 'colossus');
124	  if (idx % 5 === 4) comp.unshift(['colossus', 1 + Math.floor(idx / 10)]);   // +1 colossus per 2 cycles
125	  return comp;
126	}
127	function wavePlan(w) {
128	  const idx = Math.max(0, w - TOTAL_WAVES - 1);
129	  const cycle = Math.floor(idx / 5) + 1;
130	  // compound +10% per deep wave — maxed towers alone cannot keep up, actives required
131	  return { hpMult: Math.pow(1.10, idx) * (1 + .16 * cycle), spdMult: 1 + Math.min(.06 * (cycle - 1), .5), cycle, armorAdd: Math.floor(idx / 8) };
132	}
133	function buildSpawnQ(comp, t0 = 1) {
134	  const q = [];
135	  let gi = 0;
136	  for (const [kind, count0] of comp) {
137	    const count = Math.max(1, Math.round(count0 * swarmMult));
138	    for (let i = 0; i < count; i++) q.push({ kind, t: t0 + gi * .55 + i * SPAWN_IV[kind] });
139	    gi++;
140	  }
141	  q.sort((a, b) => a.t - b.t);
142	  return q;
143	}
144	function nextWaveText(w) {
145	  return waveComp(w).map(([k, n]) => `${ENEMY[k].zh}×${n}`).join('  ');
146	}
147	function callWave(bonus = true) {
148	  if (mode !== 'build') return false;
149	  if (bonus && callT > 0) gain(15);
150	  wave++;
151	  mode = 'combat'; combatT = 0;
152	  swarmMult = 1; rewardMult = 1; fogWave = false; overchargeT = 0;
153	  const comp = waveComp(wave);
154	  const bossWave = comp.some(g => g[0] === 'colossus');
155	  const plan = wavePlan(wave);
156	  // random event roll first (swarm must affect this wave's spawn queue);
157	  // deep waves add hostile events and the roll chance climbs per cycle
158	  if (!bossWave && Math.random() < (endless ? Math.min(.55 + .04 * plan.cycle, .8) : .4)) {
159	    const pool = Object.keys(EVENTS).filter(k => k !== lastEvent && (!EVENTS[k].deep || (endless && wave >= TOTAL_WAVES + 5)));
160	    const ev = pool[(Math.random() * pool.length) | 0];
161	    lastEvent = ev;
162	    EVENTS[ev].apply();
163	    ui.banner(EVENTS[ev].zh, EVENTS[ev].sub, 2.6);
164	  }
165	  // deep-tide cycle announcement
166	  if (endless && plan.cycle > lastCycle) {
167	    lastCycle = plan.cycle;
168	    const news = plan.cycle === 2 ? '新词缀「裂」：死亡分裂' : plan.cycle === 3 ? '新词缀「盾」：再生护盾' : plan.cycle === 4 ? '新词缀「潜」：周期潜地' : '敌群变异加剧';
169	    setTimeout(() => { ui.banner(`深 潮 循 环 ${plan.cycle}`, news, 2.4); }, 2600);
170	  }
171	  spawnQ = buildSpawnQ(comp);
172	  audio.setState(bossWave ? 'boss' : 'combat');
173	  ui.banner(bossWave ? `裂 地 巨 像${comp[0][1] > 1 ? ' ×' + comp[0][1] : ''}` : `第 ${wave} 波`, bossWave ? '踏碎大地的轰鸣' : '来袭');
174	  audio.play(bossWave ? 'roar' : 'waveStart');
175	  ui.callBtn(false);
176	  return true;
177	}
178	function gain(n) {
179	  const g = Math.floor(n * mods.essence);
180	  essence += g; ui.essencePop(g); audio.play('coin');
181	}
182	function endWave() {
183	  wavesCleared = wave;
184	  saveBest();
185	  gain(20 + 2 * wave);
186	  if (lastEvent && EVENTS[lastEvent]) { EVENTS[lastEvent].revert(); lastEvent = ''; }
187	  fx.clear();                     // in-flight starfall/ projectiles must not bleed into the next wave
188	  starfallQ = [];
189	  audio.setState('build');
190	  report('progress', { wave, score: wavesCleared });
191	  if (!endless && wave >= TOTAL_WAVES) { winGame(); return; }
192	  if (wave % 3 === 0) { startDraft(); return; }
193	  mode = 'build'; callT = 10; ui.callBtn(true, true, callT);
194	  ui.toast(`清波奖励 +${20 + 2 * wave}✦`);
195	}
196	function winGame() {
197	  mode = 'win'; audio.play('victory'); audio.setState('build');
198	  report('complete', { score: wavesCleared });
199	  ui.end({ win: true, waves: wave, best, newBest }, { endless: () => startGame(true), restart: () => startGame(false) });
200	}
201	function loseGame() {
202	  mode = 'over'; audio.play('defeat');
203	  saveBest();
204	  report('gameOver', { score: wavesCleared, progress: wave });
205	  ui.end({ win: false, waves: wave, best, newBest }, { restart: () => startGame(false) });
206	  ui.boss(null);
207	}
208	function startGame(toEndless) {
209	  resetState(toEndless);
210	  ui.hideTitle();
211	  audio.unlock(); audio.setState('build');
212	  mode = 'build'; callT = toEndless ? 8 : 18;
213	  ui.callBtn(true, true, callT);
214	  ui.banner(toEndless ? '无 尽 坚 守' : '坠 星 坚 守', toEndless ? '每 5 波一位巨像' : '点石台建塔 · 提前召唤得星尘', 2.6);
215	}
216	function startDraft() {
217	  mode = 'draft';
218	  const pool = BLESSINGS.filter(b => (counts[b.id] || 0) < b.max);
219	  const cards = []; const cand = [...pool];
220	  while (cards.length < 3 && cand.length) cards.push(cand.splice((Math.random() * cand.length) | 0, 1)[0]);

