};
window.__G = G;
window.G = G;
window.addEventListener('error', e => { if (G.err && G.err.indexOf(String(e.message || e)) < 0) G.err.push(String(e.message || e)); });

loadLevelIntoWorld(1);
mode = 'title';

// first real gesture unlocks WebAudio (and only the first one)
