  if (pl.anchor < 0) return { attached: false, dist: null, L: pl.L, angle: null, radial: null, tangential: null };
  const a = level.anchors[pl.anchor];
  const ap = anchorPos(a, pl.t);
  const dx = pl.x - ap.x, dy = pl.y - ap.y;
